<?php require 'includes/auth.php';if(user())redirect(user()['role'].'/dashboard.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=filter_var(post('email'),FILTER_VALIDATE_EMAIL);$pass=$_POST['password']??'';if(!$email||!$pass)$error='Enter a valid email and password.';else{$s=db()->prepare('SELECT * FROM users WHERE email=?');$s->execute([$email]);$u=$s->fetch();if(!$u||!password_verify($pass,$u['password_hash']))$error='Incorrect email or password.';elseif($u['status']!=='active')$error='This account is suspended.';else{login_user($u);flash('success','Welcome back, '.$u['name'].'!');redirect($u['role'].'/dashboard.php');}}}$pageTitle='Sign in';require 'includes/header.php';?><div class="auth"><div><p class="eyebrow">WELCOME BACK</p><h1>Sign in to FreshCatch</h1><p>Access your orders, shop, and marketplace account.</p></div><form method="post" class="card-form"><input type="hidden" name="csrf" value="<?=csrf()?>"><?php if($error):?><p class="field-error"><?=e($error)?></p><?php endif;?><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" minlength="8" required></label><button>Sign in</button><p>New here? <a href="register.php">Create an account</a></p></form></div><?php require 'includes/footer.php'; ?>
